const challenge = $input.first().json;
const config = $('Set Challenge Parameters').first().json;
const maxRows = Math.max(1, Math.min(10, Number(config.maxRows) || 10));
const rows = Array.isArray(challenge.top10)
  ? challenge.top10
      .filter((row) => Number.isFinite(row.bestScore))
      .slice(0, maxRows)
  : [];

const medals = ['??', '??', '??'];
const leaderboard = rows.length > 0
  ? rows.map((row, index) => {
      const rank = Number.isFinite(row.rank) ? row.rank : index + 1;
      const marker = medals[rank - 1] || `${rank}.`;
      return `${marker} ${row.name || 'Anonymous'} �� *${row.bestScore}*`;
    }).join('\n')
  : '_No scored entries yet �� be the first to take the challenge._';

const challengeUrl = `https://dubbooth.com/c/${encodeURIComponent(config.challengeId)}/`;
const status = String(challenge.status || 'unknown');
const statusLabel = status.charAt(0).toUpperCase() + status.slice(1);
const scoreCount = Number(challenge.scoredCount) || 0;
const participantCount = Number(challenge.participants) || 0;

const slackText = [
  '??? *DubBooth voice challenge leaderboard*',
  `*Score to beat:* ${challenge.targetScore ?? '��'}`,
  `*Status:* ${statusLabel} �� *Scores:* ${scoreCount} �� *Participants:* ${participantCount}`,
  '',
  leaderboard,
  '',
  `<${challengeUrl}|Open the challenge and record your take>`
].join('\n');

return [{
  json: {
    slackText,
    slackChannelId: config.slackChannelId,
    challengeUrl,
    challengeStatus: status,
    scoreCount
  }
}];
